// === Tab: mySketch ===
function setup() {
  createCanvas(920, 690);
  noFill();
  frameRate(1); // Set the frame rate to 1 shape per second
}

function draw() {
  background(255, 10); // Set a low opacity background for a trailing effect
	translate(-130, -30);
	scale(1.3);
  drawFractal(width / 2, height / 2, 400);
}

function drawFractal(x, y, size) {
  if (size < 10) return;

  let shapes = ["ellipse", "hexagon", "star", "rect", "triangle"];

  let randomShape = random(shapes);

  let r = random(255);
  let g = random(255);
  let b = random(255);
  stroke(r, g, b, 200); // Set a higher opacity for the shapes

  switch (randomShape) {
    case "ellipse":
      fill(r, g, b, 100); // Set the fill color with transparency
      ellipse(x, y, size, size);
      break;
    case "hexagon":
      fill(r, g, b, 100);
      drawHexagon(x, y, size);
      break;
    case "star":
      fill(r, g, b, 100);
      drawStar(x, y, size);
      break;
    case "rect":
      fill(r, g, b, 100);
      rectMode(CENTER);
      rect(x, y, size, size);
      break;
    case "triangle":
      fill(r, g, b, 100);
      drawTriangle(x, y, size);
      break;
  }

  let xOffset = random(-50, 50);
  let yOffset = random(-50, 50);

  drawFractal(x + size * 0.25 + xOffset, y + yOffset, size * 0.5);
  drawFractal(x - size * 0.25 + xOffset, y + yOffset, size * 0.5);
  drawFractal(x + xOffset, y - size * 0.25 + yOffset, size * 0.5);
}

function drawHexagon(x, y, s) {
  beginShape();
  for (let i = 0; i < 6; i++) {
    let angle = TWO_PI / 6 * i;
    let xPos = x + cos(angle) * s * 0.5;
    let yPos = y + sin(angle) * s * 0.5;
    vertex(xPos, yPos);
  }
  endShape(CLOSE);
}

function drawStar(x, y, s) {
  beginShape();
  for (let i = 0; i < 5; i++) {
    var angle = TWO_PI / 5 * i;
    let xPos1 = x + cos(angle) * s * 0.5;
    let yPos1 = y + sin(angle) * s * 0.5;
    vertex(xPos1, yPos1);

    angle += TWO_PI / 10;
    let xPos2 = x + cos(angle) * s * 0.25;
    let yPos2 = y + sin(angle) * s * 0.25;
    vertex(xPos2, yPos2);
  }
  endShape(CLOSE);
}

function drawTriangle(x, y, s) {
  let height = (sqrt(3) / 2) * s;
  triangle(x, y - height / 2, x - s / 2, y + height / 2, x + s / 2, y + height / 2);
}

